local A=dofile('tests/host.lua');local require=A.lib.require
local passed=0
local function test(name,f) local ok,e=xpcall(f,debug.traceback);if not ok then error('FAIL '..name..'\n'..e,0) end;passed=passed+1;print('PASS '..name) end
local function eq(a,b) assert(a==b,tostring(a)..' ~= '..tostring(b)) end
local function throws(f) assert(not pcall(f),'expected error') end
local function arr(a,b) eq(#a,#b);for i,v in ipairs(a) do eq(v,b[i]) end end
local S=require('std.collections.set').Set
local G=require('std.graph.directed').Graph
local I=require('std.ir');local C=require('std.cfg')
local function def(ty,tag,...) local fields={} for _,name in ipairs({...}) do local card=name:sub(-1);if card=='?' or card=='*' or card=='+' then name=name:sub(1,-2) else card='1' end;fields[#fields+1]={name=name,cardinality=card} end;A.define(ty,tag,fields) end
local function n(ty,tag,fields) return A.make(ty,tag,fields or {}) end
local function lit(v) return n('expression','Literal',{value=n('literal',type(v)=='boolean' and 'Boolean' or 'Integer',{value=v})}) end
for _,k in ipairs({'Integer','Boolean','String'}) do def('literal',k,'value') end
def('expression','Literal','value');def('expression','Binary','op','lhs','rhs');def('binop','Add');def('expression','Lambda','param','body');def('expression','LambdaMany','params+','body');def('expression','Application','fn','arg');def('expression','ApplicationMany','fn','args+');def('expression','Reference','name');def('expression','Invocation','fn');def('statement','Return','retval');def('funcdef',nil,'name','vars*','defn+');def('toplevel',nil,'fndef+','dir*');def('test',nil,'a?','b*','c');def('pattern','Wildcard');def('pattern','Bind','name');def('pattern','ConstructorPattern','name','args*');def('pattern','LiteralPattern','value');def('pattern','ProductPattern','elems+');def('pattern','Alternative','lhs','rhs');def('pattern','Alias','pat','name');def('matcharm',nil,'pat','guard?','body')
test('all modules load, signed interfaces and cache',function() for _,m in ipairs(MODULES) do local l=require(m);assert(A.lib.issigned(l));eq(require(m),l);assert(#A.lib.exports(l)>0);throws(function()l.__test=true end) end;eq(#MODULES,63) end)
test('derived libraries inherit without replacing parent exports',function() local p=require('std.diagnostics');local x=A.lib.derive('std/diagnostics.lua');x.Error=function()return 42 end;A.signlib(x);eq(x.Error(),42);assert(x.Error~=p.Error);eq(x.Warn,p.Warn) end)
test('collection operations',function()
 local V=require('std.collections.vector').Vector;local a=V.new({1,2});V.push(a,3);eq(V.pop(a),3);arr(V.map(a,function(x)return x*2 end),{2,4});arr(V.filter(a,function(x)return x==2 end),{2});eq(V.fold(a,0,function(x,y)return x+y end),3)
 assert(S.equal(S.union(S.new({1,2}),S.new({2,3})),S.new({1,2,3})));assert(S.equal(S.intersection(S.new({1,2}),S.new({2,3})),S.new({2})))
 local M=require('std.collections.multimap').MultiMap;local m=M.new();M.add(m,'a',false);M.add(m,'a',2);assert(M.remove(m,'a',false));arr(M.get(m,'a'),{2})
 local O=require('std.collections.orderedmap').OrderedMap;local o=O.new();O.set(o,'b',false);O.set(o,'a',1);local it=O.items(o);local k,v=it();eq(k,'b');eq(v,false);eq(O.remove(o,'b'),false);eq(O.get(o,'b'),nil)
 local W=require('std.collections.worklist').Worklist;local w=W.new({1,2,1});eq(W.pop(w),1);W.push(w,1);eq(W.pop(w),2);eq(W.pop(w),1);assert(W.empty(w))
 local B=require('std.collections.bitset').BitSet;local b=B.new({0,31,32,1000});B.remove(b,31);arr(B.values(b),{0,32,1000});arr(B.values(B.intersection(b,B.new({32,31}))),{32})
 local Q=require('std.collections.priorityqueue').PriorityQueue;local q=Q.new();for _,x in ipairs({5,1,3,2}) do Q.push(q,x) end;arr({Q.pop(q),Q.pop(q),Q.pop(q),Q.pop(q)},{1,2,3,5})
end)
test('graph traversal, SCC, topology, dominators, loops and shortest path',function()
 local g=G.new({'s','a','b','j','z','dead'},{{'s','a'},{'s','b'},{'a','j'},{'b','j'},{'j','z'},{'z','j'}})
 local R=require('std.graph.reachability');assert(R.Reachable(g,{'s'}).z);assert(not R.Reachable(g,{'s'}).dead);arr(R.Path(g,'s','z'),{'s','a','j','z'})
 local K=require('std.graph.scc');local groups=K.Tarjan(g);local _,w=K.Condensation(g,groups);eq(w.j,w.z);eq(#groups,#K.Kosaraju(g));assert(require('std.graph.topology').Topological(g)==nil);assert(require('std.graph.topology').Topological(K.Condensation(g)))
 local D=require('std.graph.dominators');local d=D.Dominators(g,'s');assert(d.j.s and not d.j.a and not d.dead);local id=D.ImmediateDominators(g,'s',d);eq(id.j,'s');eq(id.z,'j');assert(D.Frontier(g,'s').a.j);assert(D.Frontier(g,'s').z.j);eq(#require('std.graph.loops').NaturalLoops(g,'s'),1)
 local dist=require('std.graph.shortestpath').Dijkstra(g,'s',function(a,b)return a=='a' and 10 or 1 end);eq(dist.z,3)
end)
test('HM inference, polymorphic instantiation, occurs check, constructors',function()
 local H=require('std.types.hm');local E=require('std.semantics.environment').Env;local e=E.prelude('MiniML');local a=H.Fresh();local scheme=H.Generalize(e,H.Arrow(a,a));eq(#scheme.quantified,1);local i,b=H.Named('int'),H.Named('bool');local f=H.Instantiate(scheme);H.Unify(f,H.Arrow(i,i));local g=H.Instantiate(scheme);H.Unify(g,H.Arrow(b,b));throws(function()H.Unify(i,b) end);local x=H.Fresh();throws(function()H.Unify(x,H.Arrow(x,i))end)
 local localenv=E.bind_value(e,'x',H.Mono(a));eq(#H.Generalize(localenv,a).quantified,0);eq(E.type_arity(e,'int'),0);e=E.declare_type(e,'option',1);e=E.declare_ctor(e,'Some',H.CtorScheme({a},{a},H.Named('option',{a})));local args,res=H.InstantiateCtor(E.lookup_ctor(e,'Some'));eq(args[1],res.args[1]);assert(H.Pretty(scheme):find('forall',1,true))
 local U=require('std.types.unification');local t=U.Term('f',{U.Var('x')});local s=assert(U.Unify(t,U.Term('f',{U.Term('a')})));eq(U.Apply(t,s).args[1].symbol,'a');assert(not U.Unify(U.Var('x'),t));assert(require('std.match.unification').Unify(U.Var('x'),U.Term('a')))
 local T=require('std.types.constraints');local c=T.New();local v=H.Fresh();T.Equal(c,v,i);T.Solve(c);eq(H.Prune(v).name,'int');local L=require('std.types.lattice').Powerset(S.new({'a','b'}));assert(L.Leq(L.Bottom(),L.Top()));eq(require('std.types.lattice').Finite({1,2,3},function(x,y)return x<=y end).Join(1,3),3);assert(require('std.types.subtyping').IsSubtype('Dog','Animal',{Dog={'Animal'}}))
end)
test('pattern coverage: recursive constructors, guards, booleans and redundancy',function()
 local H=require('std.types.hm');local E=require('std.semantics.environment').Env;local e=E.prelude();local a=H.Fresh();local t=H.Named('list',{a});e=E.declare_type(e,'list',1);e=E.declare_ctor(e,'Nil',H.CtorScheme({a},{},t));e=E.declare_ctor(e,'Cons',H.CtorScheme({a},{a,t},t));local w=n('pattern','Wildcard');local nilp=n('pattern','ConstructorPattern',{name='Nil',args={}});local cons=n('pattern','ConstructorPattern',{name='Cons',args={w,w}});local function arm(p,g)return n('matcharm',nil,{pat=p,guard=g,body=lit(0)})end
 local P=require('std.semantics.patterns');local r=P.CheckCoverage(e,t,{arm(cons)});assert(not r.exhaustive);eq(r.witness,'Nil');r=P.CheckCoverage(e,t,{arm(nilp),arm(cons),arm(w)});assert(r.exhaustive);eq(#r.redundant,1);assert(not P.CheckCoverage(e,t,{arm(w,lit(true))}).exhaustive)
 local D=require('std.match.decisiontree');local bool={{pattern={tag='lit',value=true},domains={}},{pattern={tag='lit',value=false},domains={}}};local rr=D.Coverage({{pattern={tag='lit',value=true}}},bool);eq(rr.witness.value,false);local f=D.Compile({{pattern={tag='lit',value=1},action=function()return 'one'end},{pattern={tag='wild'}}},function()end);local ix,val=f(1);eq(ix,1);eq(val,'one');eq(f(2),2)
end)
test('serialization, AST rewrites, structural matching and traversal',function()
 local J=require('std.serialize');local x=n('test',nil,{b={lit(42),lit(false)},c='hi\n🌱'});local j=J.JSON(x);eq(J.JSON(J.FromJSON(j)),j);eq(J.JSON(J.FromBinary(J.Binary(x))),j);eq(J.DecodeJSON('"\\ud83d\\ude00"'),'😀');eq(J.JSON(J.DecodeJSON('[null,false,{},[]]')),'[null,false,{},[]]');for _,bad in ipairs({'01','1.','[1,]','{"a":1,"a":2}','"\\ud800"','true false'}) do throws(function()J.DecodeJSON(bad)end) end;local cyc={};cyc.x=cyc;throws(function()J.JSON(cyc)end)
 local R=require('std.rewrite');local expr=n('expression','Binary',{op=n('binop','Add'),lhs=lit(20),rhs=lit(22)});eq(A.destruct(A.destruct(R.ConstFold(expr))),42);local lambda=n('expression','LambdaMany',{params={'x','y'},body=lit(1)});eq(A.tag(R.Curry(lambda)),'Lambda');local M=require('std.match.structural');local p=M.Node('expression','Literal',{value=M.Capture('x')});assert(M.Match(p,lit(2)).x);eq(A.destruct(A.destruct(M.Replace(lit(2),p,function()return lit(5)end))),5)
 local Tree=require('std.tree').Tree;eq(#Tree.collect(x,function(z)return A.tag(z)=='Literal'end),2);eq(Tree.fold(x,0,function(a)return a+1 end),5);assert(J.SExpr(x):find('(Literal',1,true));local f=n('funcdef',nil,{name='f',vars={},defn={n('statement','Return',{retval=lit(7)})}});local g=n('funcdef',nil,{name='main',vars={},defn={n('statement','Return',{retval=n('expression','Invocation',{fn='f'})})}});local root=n('toplevel',nil,{fndef={f,g},dir={}});eq(A.tag(R.Inline(root,'f').values.fndef[2].values.defn[1].values.retval),'Literal')
end)
test('scope capture, diagnostics, control and C3 inheritance',function()
 local Scope=require('std.scope').Scope;local owner=lit(1);local ctx={};local s=Scope.new(nil,'method',owner,ctx);local b=Scope.declare(s,'x','local');local child=Scope.new(s,'block',lit(2),ctx);local grand=Scope.new(child,'block',lit(3),ctx);eq(Scope.resolve(grand,'x'),b);Scope.finish(grand);eq(A.annotation(grand.owner,'captures')[1].id,b.id);assert(child.captures[b.id]);local Bind=require('std.semantics.bindings');Bind.MarkRead(b);eq(#Bind.Unused(s),0)
 local Co=require('std.control').Control;local frame=Co.enter(nil,'method',owner,ctx);local blk=Co.enter(frame,'block',lit(3),ctx);eq(Co.target(blk,'Return'),frame);eq(Co.target(blk,'Break'),blk);local diag=require('std.diagnostics');local mark=diag.Checkpoint();diag.Error(diag.FaultPattern('E1','bad %s'),owner,'thing');assert(diag.FailedSince(mark));local inh=require('std.semantics.inheritance');arr(inh.Linearize({O={},A={'O'},B={'O'},C={'A','B'}},'C'),{'C','A','B','O'});throws(function()inh.Linearize({A={'B'},B={'A'}},'A')end);local eff=require('std.semantics.effects');assert(eff.Pure(eff.Effects(owner,function()return {}end)))
end)
-- Small independent interpreter for the specified expression IR and closure-converted output.
local function eval(x,env,functions)
 local t=x.tag;if t=='const' then return x.value elseif t=='var' then assert(env[x.name]~=nil,'unbound '..x.name);return env[x.name] elseif t=='lambda' then return function(a)local e=setmetatable({[x.param]=a},{__index=env});return eval(x.body,e,functions)end elseif t=='app' then local f=eval(x.fn,env,functions);return f(eval(x.arg,env,functions)) elseif t=='let' then local v=eval(x.value,env,functions);return eval(x.body,setmetatable({[x.name]=v},{__index=env}),functions) elseif t=='if' then if eval(x.cond,env,functions) then return eval(x.yes,env,functions) else return eval(x.no,env,functions) end elseif t=='prim' or t=='tuple' then local args={} for i,a in ipairs(x.args) do args[i]=eval(a,env,functions) end;if t=='tuple' then return args end;return require('std.transform.constfold').Primitives()[x.op](table.unpack(args)) elseif t=='closure' then local f=functions[x.code];local captured={} for i,a in ipairs(x.captures) do captured[f.captures[i]]=eval(a,env,functions) end;return function(v)return eval(f.body,setmetatable({[f.param]=v},{__index=captured}),functions)end elseif t=='invoke' then local f=eval(x.closure,env,functions);return f(eval(x.arg,env,functions)) elseif t=='lifted_call' then local f=eval({tag='closure',code=x.code,captures=x.captures},env,functions);return f(eval(x.arg,env,functions)) end;error(t) end
local function closed_eval(prog) local f={} for _,v in ipairs(prog.functions) do f[v.name]=v end;return eval(prog.body,{},f) end
test('ANF, CPS, closure conversion, lambda lifting, inlining and folding preserve results',function()
 local expr=I.Let('x',I.Const(7),I.App(I.Lambda('y',I.Prim('+',{I.Var('x'),I.Var('y')})),I.Prim('*',{I.Const(5),I.Const(7)})));eq(eval(expr,{}),42)
 eq(eval(require('std.transform.anf').ANormalize(expr),{}),42);eq(eval(require('std.transform.cps').CPSConvert(expr),{})(function(x)return x end),42);eq(closed_eval(require('std.transform.closureconv').ClosureConvert(expr)),42);eq(closed_eval(require('std.transform.lambdalift').LambdaLift(expr)),42);eq(eval(require('std.transform.inline').Inline(expr),{}),42);eq(eval(require('std.transform.constfold').ConstFold(expr),{}),42);eq(eval(require('std.transform.deadcode').DeadEliminate(I.Let('z',I.Const(0),expr)),{}),42)
 local s=I.Substitute(I.Lambda('y',I.Var('x')),'x',I.Var('y'));assert(s.param~='y' and I.Free(s).y);local captures=require('std.semantics.closures').Captures(I.Lambda('y',I.Var('x')));arr(captures,{'x'});local div=I.Prim('/',{I.Const(1),I.Const(0)});eq(require('std.transform.constfold').ConstFold(div).tag,'prim')
 local p=require('std.testing.property');assert(p.ForAll(p.Integer(-100,100),function(x)local e=I.App(I.Lambda('x',I.Prim('+',{I.Var('x'),I.Const(3)})),I.Const(x));return eval(require('std.transform.anf').ANormalize(e),{})==x+3 and eval(require('std.transform.cps').CPSConvert(e),{})(function(z)return z end)==x+3 end,{runs=100,seed=12}))
end)
local function instr(op,defs,uses,targets) return {op=op,defs=defs or {},uses=uses or {},targets=targets or {}} end
local function diamond() return C.New('s',{s={instrs={instr('param',{'c'})},term=instr('branch',{}, {'c'},{'a','b'})},a={instrs={instr('const',{'x'})},term=instr('jump',{}, {},{'j'})},b={instrs={instr('const',{'x'})},term=instr('jump',{}, {},{'j'})},j={instrs={},term=instr('ret',{}, {'x'})}},{'s','a','b','j'}) end
test('CFG dataflow, reaching definitions, liveness, def-use, SSA and phi lowering',function()
 local cfg=diamond();local L=require('std.analysis.liveness');assert(L.LiveIn(cfg).j.x);assert(L.LiveOut(cfg).a.x);assert(not L.LiveIn(cfg).a.x);assert(L.Interference(cfg).out.x)
 local R=require('std.analysis.reachingdefs');local ins,_,defs=R.ReachingDefinitions(cfg);eq(S.size(ins.j),3);local U=require('std.analysis.defuse').DefUse(cfg);eq(#U.uses[#U.uses].definitions,2)
 local SSA=require('std.transform.ssa');local ss=SSA.ToSSA(cfg);local phi=ss.blocks.j.phis[1];assert(phi.args.a~=phi.args.b);eq(ss.blocks.j.term.uses[1],phi.dest);eq(#SSA.InsertPhi(cfg).blocks.j.phis,1);local lower=SSA.FromSSA(ss);C.Validate(lower);eq(#lower.order,6);assert(lower.blocks.j.phis==nil);assert(not lower.ssa);local counts=require('std.analysis.usecounts').UseCounts(ss);assert(counts[phi.args.a]==1);local si,so=L.Liveness(ss);assert(so.a[phi.args.a] and not so.a[phi.args.b]);assert(not si.j[phi.dest]);local CF=require('std.semantics.controlflow');eq(#CF.Unreachable(cfg),0);assert(CF.PostDominators(cfg).s.j)
 local D=require('std.analysis.dataflow');eq(D.FixedPoint(0,function(v)return math.min(3,v+1)end,function(a,b)return a==b end),3);local AI=require('std.analysis.abstractinterp');local lat=AI.ConstantLattice();eq(lat.Join(lat.Constant(1),lat.Constant(2)).tag,'top');local g=C.Graph(cfg);local ai=AI.Interpret(g,lat,function(_,v)return v end,{s=lat.Constant(1)});eq(ai.j.value,1)
 local call=require('std.analysis.callgraph').CallGraph({{name='f'},{name='g'}},function(f)return f.name=='f' and {'g'} or {}end);assert(require('std.analysis.escape').Escapes(call,{'f'},'g'))
end)
test('pretty-printing, graph formats and testing helpers',function()
 local P=require('std.format.pretty');local d=P.Group(P.Concat(P.Text('hello'),P.Nest(2,P.Concat(P.Line(),P.Text('world')))));eq(P.Render(d,20),'hello world');eq(P.Render(d,5),'hello\n  world');local g=G.new({'a','b'},{{'a','b'}});assert(require('std.format.dot').DependencyGraph(g):find('n1 -> n2',1,true));assert(require('std.format.mermaid').DependencyGraph(g):find('n1 --> n2',1,true));eq(require('std.format.html').Escape('<&>'),'&lt;&amp;&gt;')
 local T=require('std.testing.assertions');T.Equal(1,1);T.Throws(function()error('bad')end,'bad');T.Structural(lit(1),lit(1));local F=require('std.testing.fixtures');eq(F.Run({{name='a',run=function()end},{name='b',run=function()error('fail')end}}).failed,1);local Pp=require('std.testing.property');local ok,r=Pp.ForAll(Pp.Integer(1,20),function()return false end,{shrink=function(v)return v>1 and {v-1} or {}end});assert(not ok);eq(r.case,1);local store={};local snap=require('std.testing.snapshot').Snapshot;assert(snap('a','x',function(k)return store[k]end,function(k,v)store[k]=v end,true));assert(snap('a','x',function(k)return store[k]end))
end)
